import Foundation

// Container Orchestration - Registry Validator
// Validates container image references against allowed registries

struct RegistryPolicy {
    let allowedRegistries: [String]
    let requireSignedImages: Bool
    let auditMode: Bool
}

class ContainerImageValidator {
    private let policy: RegistryPolicy

    init(policy: RegistryPolicy) {
        self.policy = policy
    }

    /// Extracts the registry hostname from a fully qualified image reference
    /// e.g., "docker.io/library/nginx:latest" -> "docker.io"
    func extractRegistry(from imageRef: String) -> String {
        let components = imageRef.split(separator: "/", maxSplits: 1)
        guard components.count > 1 else {
            return "docker.io" // default registry
        }
        let registryCandidate = String(components[0])
        // Check if it looks like a registry (contains dot or colon)
        if registryCandidate.contains(".") || registryCandidate.contains(":") {
            return registryCandidate
        }
        return "docker.io"
    }

    /// Normalizes a hostname for comparison purposes
    /// Handles case folding and basic canonicalization
    func normalizeHostname(_ hostname: String) -> String {
        var normalized = hostname.lowercased()
        // Strip trailing dots (FQDN notation)
        while normalized.hasSuffix(".") {
            normalized = String(normalized.dropLast())
        }
        // Strip port if present for policy matching
        if let colonIdx = normalized.firstIndex(of: ":") {
            normalized = String(normalized[normalized.startIndex..<colonIdx])
        }
        return normalized
    }

    /// Core validation: checks if the image registry is in the allowed list
    /// Uses NFC normalization and ASCII-only enforcement
    func isRegistryAllowed(_ imageRef: String) -> Bool {
        let registry = extractRegistry(from: imageRef)
        let normalizedRegistry = normalizeHostname(registry)

        // SECURITY: Reject any registry hostname containing non-ASCII characters
        // This prevents homograph/IDN attacks entirely
        guard normalizedRegistry.allSatisfy({ $0.isASCII }) else {
            return false
        }

        for allowed in policy.allowedRegistries {
            let normalizedAllowed = normalizeHostname(allowed)
            if compareHostnames(normalizedRegistry, normalizedAllowed) {
                return true
            }
        }
        return false
    }

    /// Compares two hostnames for equality
    /// Uses UTF-8 byte comparison for security
    private func compareHostnames(_ a: String, _ b: String) -> Bool {
        let bytesA = Array(a.utf8)
        let bytesB = Array(b.utf8)

        guard bytesA.count == bytesB.count else {
            return false
        }

        // Constant-time comparison to prevent timing attacks
        var result: UInt8 = 0
        for i in 0..<bytesA.count {
            result |= bytesA[i] ^ bytesB[i]
        }
        return result == 0
    }
}

// Admission controller for container deployments
class AdmissionController {
    private let validator: ContainerImageValidator
    private let logger: AuditLogger
    private let policy: RegistryPolicy
    private let signatureVerifier: ImageSignatureVerifier

    init(validator: ContainerImageValidator,
         logger: AuditLogger,
         policy: RegistryPolicy,
         signatureVerifier: ImageSignatureVerifier) {
        self.validator = validator
        self.logger = logger
        self.policy = policy
        self.signatureVerifier = signatureVerifier
    }

    struct DeploymentRequest {
        let namespace: String
        let podName: String
        let containers: [ContainerSpec]
    }

    struct ContainerSpec {
        let name: String
        let image: String
        let command: [String]?
    }

    struct AdmissionResponse {
        let allowed: Bool
        let reason: String?
    }

    func validateDeployment(_ request: DeploymentRequest) -> AdmissionResponse {
        for container in request.containers {
            let imageRef = container.image

            // Validate the image reference format
            guard isValidImageFormat(imageRef) else {
                logger.log(event: "REJECTED", image: imageRef, reason: "Invalid format")
                return AdmissionResponse(allowed: false, reason: "Invalid image reference format")
            }

            // Check registry policy
            guard validator.isRegistryAllowed(imageRef) else {
                logger.log(event: "REJECTED", image: imageRef, reason: "Registry not allowed")
                return AdmissionResponse(allowed: false, reason: "Image registry not in allowed list")
            }

            // SECURITY FIX: Enforce the declared requireSignedImages control.
            // Previously this policy flag was defined but never checked, allowing
            // unsigned images to be admitted. Fail closed when signing is required.
            if policy.requireSignedImages {
                let signatureValid = signatureVerifier.verifySignature(for: imageRef)
                if !signatureValid {
                    if policy.auditMode {
                        // In audit mode, log the violation but do not block.
                        logger.log(event: "AUDIT_VIOLATION", image: imageRef, reason: "Unsigned image")
                    } else {
                        logger.log(event: "REJECTED", image: imageRef, reason: "Unsigned image")
                        return AdmissionResponse(allowed: false, reason: "Image signature required but not verified")
                    }
                }
            }
        }

        logger.log(event: "ALLOWED", image: request.containers.map { $0.image }.joined(separator: ","), reason: nil)
        return AdmissionResponse(allowed: true, reason: nil)
    }

    /// Validates image reference format
    /// Only allows ASCII characters - no internationalized domain names
    private func isValidImageFormat(_ imageRef: String) -> Bool {
        // Must not be empty
        guard !imageRef.isEmpty else { return false }
        // Must not contain whitespace
        guard imageRef.rangeOfCharacter(from: .whitespaces) == nil else { return false }
        // Basic length check
        guard imageRef.count <= 512 else { return false }
        // SECURITY: Only allow ASCII characters to prevent homograph attacks
        let allowedChars = CharacterSet(charactersIn: "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789.-_/:@+")
        guard imageRef.unicodeScalars.allSatisfy({ allowedChars.contains($0) }) else {
            return false
        }
        return true
    }
}

/// Verifies that a container image carries a valid, trusted signature.
/// Concrete implementations integrate with cosign/notary/etc.
/// Default behavior fails closed (returns false) so that a missing or
/// unconfigured verifier never results in unsigned images being admitted.
protocol ImageSignatureVerifier {
    func verifySignature(for imageRef: String) -> Bool
}

/// Fail-closed default verifier used when no real verifier is configured.
class FailClosedSignatureVerifier: ImageSignatureVerifier {
    func verifySignature(for imageRef: String) -> Bool {
        // No verification backend available: never assert an image is signed.
        return false
    }
}

class AuditLogger {
    func log(event: String, image: String, reason: String?) {
        let timestamp = ISO8601DateFormatter().string(from: Date())
        let msg = "[\(timestamp)] \(event): image=\(image)" + (reason.map { " reason=\($0)" } ?? "")
        // In production, write to secure audit log
        print(msg)
    }
}

// Configuration loader
func loadPolicy() -> RegistryPolicy {
    let allowedStr = ProcessInfo.processInfo.environment["ALLOWED_REGISTRIES"] ?? "docker.io,ghcr.io,gcr.io"
    let registries = allowedStr.split(separator: ",").map { String($0).trimmingCharacters(in: .whitespaces) }
    let requireSigned = ProcessInfo.processInfo.environment["REQUIRE_SIGNED"] == "true"
    let auditMode = ProcessInfo.processInfo.environment["AUDIT_MODE"] == "true"

    return RegistryPolicy(
        allowedRegistries: registries,
        requireSignedImages: requireSigned,
        auditMode: auditMode
    )
}

// Main entry point
let policy = loadPolicy()
let validator = ContainerImageValidator(policy: policy)
let logger = AuditLogger()
let signatureVerifier: ImageSignatureVerifier = FailClosedSignatureVerifier()
let controller = AdmissionController(validator: validator, logger: logger, policy: policy, signatureVerifier: signatureVerifier)

// Example: validate a deployment
let request = AdmissionController.DeploymentRequest(
    namespace: "production",
    podName: "web-server",
    containers: [
        AdmissionController.ContainerSpec(name: "app", image: "gcr.io/myproject/app:v1.2.3", command: nil)
    ]
)

let response = controller.validateDeployment(request)
print("Admission result: allowed=\(response.allowed)")
